def comps_conn(g, diagonal=False):
 R0,C0=len(g),len(g[0]); seen=set(); out=[]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 if diagonal: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(R0):
  for c in range(C0):
   v=g[r][c]
   if v==6 or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));cells=[]
   while q:
    a,b=q.pop();cells.append((a,b))
    for dr,dc in dirs:
     x,y=a+dr,b+dc
     if 0<=x<R0 and 0<=y<C0 and (x,y) not in seen and g[x][y]==v:
      seen.add((x,y));q.append((x,y))
   out.append((v,cells))
 return out
